import heapq

def match(orders):
    trades = []
    seq_counter = 0

    # order_id -> [side, price, qty, seq]
    book = {}

    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)

    def add_to_book(order_id, side, price, qty, seq):
        book[order_id] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, order_id))
        else:
            heapq.heappush(sell_heap, (price, seq, order_id))

    def match_incoming(incoming_id, side, price, qty, is_market):
        # price is None if market order (is_market True), else the limit/ioc price
        remaining = qty
        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            top = heap[0]
            if side == 'buy':
                top_price, top_seq, top_id = top
            else:
                neg_price, top_seq, top_id = top
                top_price = -neg_price

            # check validity (lazy deletion)
            if top_id not in book or book[top_id][2] <= 0:
                heapq.heappop(heap)
                continue

            resting_side, resting_price, resting_qty, resting_seq = book[top_id]

            # check price condition
            if not is_market:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            # pop it since we're going to modify or fully consume it
            heapq.heappop(heap)

            trade_qty = min(remaining, resting_qty)
            trade_price = resting_price

            if side == 'buy':
                buy_id = incoming_id
                sell_id = top_id
            else:
                buy_id = top_id
                sell_id = incoming_id

            trades.append([buy_id, sell_id, trade_price, trade_qty])

            remaining -= trade_qty
            resting_qty -= trade_qty

            if resting_qty > 0:
                book[top_id][2] = resting_qty
                # push back onto heap
                if resting_side == 'buy':
                    heapq.heappush(buy_heap, (-resting_price, resting_seq, top_id))
                else:
                    heapq.heappush(sell_heap, (resting_price, resting_seq, top_id))
            else:
                # fully filled, remove from book
                if top_id in book:
                    del book[top_id]

        return remaining

    for order in orders:
        otype = order[0]

        if otype == 'cancel':
            order_id = order[1]
            if order_id in book:
                del book[order_id]
            continue

        order_id = order[1]
        side = order[2]

        if otype == 'market':
            qty = order[3]
            remaining = match_incoming(order_id, side, None, qty, True)
            # discard remainder
        elif otype == 'ioc':
            price = order[3]
            qty = order[4]
            remaining = match_incoming(order_id, side, price, qty, False)
            # discard remainder
        elif otype == 'limit':
            price = order[3]
            qty = order[4]
            remaining = match_incoming(order_id, side, price, qty, False)
            if remaining > 0:
                add_to_book(order_id, side, price, remaining, seq_counter)
                seq_counter += 1
        else:
            continue

        seq_counter += 1

    return trades

